class Solution {
public:
    int maximumLength(string s) {
        int n = s.size();
        int top1[26] = {0}, top2[26] = {0}, top3[26] = {0};

        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s[j] == s[i]) j++;
            int len = j - i;
            int c = s[i] - 'a';
            if (len >= top1[c]) {
                top3[c] = top2[c];
                top2[c] = top1[c];
                top1[c] = len;
            } else if (len >= top2[c]) {
                top3[c] = top2[c];
                top2[c] = len;
            } else if (len > top3[c]) {
                top3[c] = len;
            }
            i = j;
        }

        int ans = 0;
        for (int c = 0; c < 26; c++) {
            int candidate = top1[c] - 2;
            if (top2[c] - 1 > candidate) candidate = top2[c] - 1;
            if (top3[c] > candidate) candidate = top3[c];
            if (candidate > ans) ans = candidate;
        }
        return ans > 0 ? ans : -1;
    }
};
